using System;
using System.Web;

namespace InformationWeb
{
    /// <summary>Chuyển về trang 404 khi slug/cate không tồn tại hoặc link không đúng chuẩn.</summary>
    public static class NotFoundHelper
    {
        public const string NotFoundPath = "~/NotFound.aspx";

        /// <summary>Chuyển request sang trang NotFound.aspx và trả về HTTP 404. Gọi khi slug/cate không tìm thấy.</summary>
        public static void TransferToNotFound()
        {
            var ctx = HttpContext.Current;
            if (ctx == null) return;
            //ctx.Response.StatusCode = 404;
            ctx.Server.Transfer(NotFoundPath);
        }

        /// <summary>Path có 2 segment liền kề trùng nhau (vd. tin-tuc/tin-tuc) — URL không hợp lệ.</summary>
        public static bool HasDuplicateAdjacentPathSegments(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            string trimmed = path.Trim().Trim('/');
            if (string.IsNullOrEmpty(trimmed)) return false;
            string[] parts = trimmed.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < parts.Length - 1; i++)
            {
                if (string.Equals(parts[i], parts[i + 1], StringComparison.OrdinalIgnoreCase))
                    return true;
            }
            return false;
        }

        /// <summary>Gộp segment liền kề trùng nhau: tin-tuc/tin-tuc → tin-tuc.</summary>
        public static string CollapseDuplicateAdjacentPathSegments(string path)
        {
            if (string.IsNullOrEmpty(path)) return "";
            string trimmed = path.Trim().Trim('/');
            if (string.IsNullOrEmpty(trimmed)) return "";
            string[] parts = trimmed.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length <= 1) return trimmed;

            string[] kept = new string[parts.Length];
            int keptCount = 0;
            kept[keptCount++] = parts[0];
            for (int i = 1; i < parts.Length; i++)
            {
                if (!string.Equals(parts[i], parts[i - 1], StringComparison.OrdinalIgnoreCase))
                    kept[keptCount++] = parts[i];
            }

            if (keptCount == 1) return kept[0];
            return string.Join("/", kept, 0, keptCount);
        }
    }
}

